[[nodiscard]] std::optional<std::pair<std::size_t, std::size_t>>
scoreClipPlayerCoordinates(std::string_view nodeId) noexcept
{
    constexpr std::string_view prefix{"scoreClipPlayer_"};
    if (!nodeId.starts_with(prefix))
        return std::nullopt;
    nodeId.remove_prefix(prefix.size());
    const auto separator = nodeId.find('_');
    if (separator == std::string_view::npos)
        return std::nullopt;
    std::size_t clip = 0;
    std::size_t channel = 0;
    const auto clipText = nodeId.substr(0, separator);
    const auto channelText = nodeId.substr(separator + 1U);
    const auto clipParsed = std::from_chars(
        clipText.data(), clipText.data() + clipText.size(), clip);
    const auto channelParsed = std::from_chars(
        channelText.data(), channelText.data() + channelText.size(), channel);
    if (clipParsed.ec != std::errc{}
        || clipParsed.ptr != clipText.data() + clipText.size()
        || channelParsed.ec != std::errc{}
        || channelParsed.ptr != channelText.data() + channelText.size())
    {
        return std::nullopt;
    }
    return std::pair{clip, channel};
}

[[nodiscard]] PreparedScoreClipAudioPtr scoreClipAudioForNode(
    const RenderSettings& settings,
    std::string_view nodeId) noexcept
{
    const auto coordinates = scoreClipPlayerCoordinates(nodeId);
    if (!coordinates.has_value() || settings.preparedScore == nullptr
        || coordinates->first >= settings.preparedScore->clips().size())
    {
        return {};
    }
    const auto& clip = settings.preparedScore->clips()[coordinates->first];
    const auto found = std::ranges::find_if(
        settings.preparedScoreClipAudio,
        [&](const auto& candidate) {
            return candidate != nullptr && candidate->clipId == clip.clipId;
        });
    if (found == settings.preparedScoreClipAudio.end()
        || !(*found)->valid()
        || (*found)->binding != settings.preparedScore->binding()
        || coordinates->second >= (*found)->channels.size())
    {
        return {};
    }
    return *found;
}

[[nodiscard]] bool isPreparedScoreClipResource(
    const RenderSettings& settings,
    std::string_view resourceId) noexcept
{
    constexpr std::string_view prefix{"score-clip-audio-"};
    if (!resourceId.starts_with(prefix))
        return false;
    auto coordinatesText = resourceId.substr(prefix.size());
    const auto separator = coordinatesText.find('-');
    if (separator == std::string_view::npos)
        return false;
    const auto nodeId = std::string{"scoreClipPlayer_"}
        + std::string{coordinatesText.substr(0, separator)} + "_"
        + std::string{coordinatesText.substr(separator + 1U)};
    return scoreClipAudioForNode(settings, nodeId) != nullptr;
}

struct InputEndpoint
{
    std::string nodeId;
    std::string portId;

    [[nodiscard]] bool operator==(const InputEndpoint&) const = default;
};

struct InputEndpointHash
{
    [[nodiscard]] std::size_t operator()(const InputEndpoint& endpoint) const
    {
        const auto nodeHash = std::hash<std::string>{}(endpoint.nodeId);
        const auto portHash = std::hash<std::string>{}(endpoint.portId);
        return nodeHash ^ (portHash + 0x9e3779b97f4a7c15ULL + (nodeHash << 6) + (nodeHash >> 2));
    }
};

