struct ParameterOverride
{
    std::optional<std::string> expression;
    std::optional<std::string> choice;
    std::optional<bool> boolean;
    std::optional<std::string> resource;
    std::optional<std::string> text;
};

// A Constant whose valueRange is unitRange
// keeps its Value from -1 to 1; the default, unbounded, keeps any number.
[[nodiscard]] bool constantKeepsUnitRange(
    const std::unordered_map<std::string, ParameterOverride>& overrides)
{
    const auto found = overrides.find("valueRange");
    return found != overrides.end() && found->second.choice == std::optional<std::string>{"unitRange"};
}

