        {
            addDiagnostic(
                context.diagnostics,
                DiagnosticCode::ParameterEvaluationError,
                node.instanceId,
                {},
                descriptorParameter.id,
                "SingleSideBandRM freqScale must be finite and positive");
            continue;
        }

        // Grains play ratios from 1/64 through 64; projects before
        // format 83 shift by a phase vocoder from 0.5 through 2.
        const auto frequencyScaleGrains = [&] {
            const auto scaling = overrides.find("scaling");
            return scaling == overrides.end() || scaling->second.choice != "legacyVocoder";
        };
        if (node.typeId == "talas.frequencyScale"
            && descriptorParameter.id == "frequencyScale"
            && !supportedFrequencyScale(frequencyScaleGrains(),
                evaluation.value.value))
        {
            addDiagnostic(
                context.diagnostics,
                DiagnosticCode::ParameterEvaluationError,
                node.instanceId,
                {},
                descriptorParameter.id,
                frequencyScaleGrains()
                    ? "FrequencyScale frequencyScale must be finite from 1/64 through 64"
                    : "FrequencyScale frequencyScale must be finite from 0.5 through 2");
            continue;
        }
