// CDP's submix faders with two files: its balance file read once, when it
// starts, its times from the Sound's start, and its gain, which it takes as
// a breakpoint file and reads at every frame, a block at a time.
[[nodiscard]] bool renderCdpMixFaders(
    OfflineRenderResult& result,
    const RuntimePlan& plan,
    const RenderSettings& settings,
    RenderBuffers& buffers,
    const CompileStep& step,
    talas::cdp::MixFaders& state)
{
    auto* output = requireOutputBuffer(
        result, plan, buffers, step, "audioOut", talas::core::PortType::Audio);
    const auto* input = requireInputBuffer(
        result, plan, buffers, step, "audioIn", talas::core::PortType::Audio);
    const auto* side = requireInputBuffer(
        result, plan, buffers, step, "sideChain", talas::core::PortType::Audio);
    const auto* balance = requireTextParameter(result, step, "balance");
    const auto* gain = requireParameter(result, step, "gain");
    if (output == nullptr || input == nullptr || side == nullptr || balance == nullptr || gain == nullptr)
        return false;
    if (!state.prepared())
    {
        const auto lines = cdp_mix_faders::readBalance(*balance);
        if (!lines.has_value() || !state.prepare(settings.sampleRate, *lines, *gain))
        {
            addRenderStructuralDiagnostic(result, step.nodeId, {}, "balance",
                "CDP Mix Faders requires a balance of lines of a time in seconds, the first 0 and the others at least a frame after it, and the input's and side chain's levels, neither negative nor both 0, and a gain from 0 to 256");
            return false;
        }
    }
    if (!state.setGain(*gain))
    {
        addRenderStructuralDiagnostic(result, step.nodeId, {}, "gain",
            "CDP Mix Faders requires a gain from 0 to 256");
        return false;
    }
    if (!state.process(*input, *side, *output))
    {
        addRenderStructuralDiagnostic(result, step.nodeId, "audioIn", {},
            "CDP Mix Faders requires finite input and side chain");
        return false;
    }
    return true;
}

