// CDP's submix inbetween, one of its files: its mode and ratio, or count and
// file, read once, when it starts.
[[nodiscard]] bool renderCdpMixInbetween(
    OfflineRenderResult& result,
    const RuntimePlan& plan,
    RenderBuffers& buffers,
    const CompileStep& step,
    talas::cdp::MixInbetween& state)
{
    auto* output = requireOutputBuffer(
        result, plan, buffers, step, "audioOut", talas::core::PortType::Audio);
    const auto* input = requireInputBuffer(
        result, plan, buffers, step, "audioIn", talas::core::PortType::Audio);
    const auto* side = requireInputBuffer(
        result, plan, buffers, step, "sideChain", talas::core::PortType::Audio);
    const auto* mode = requireChoiceParameter(result, step, "mode");
    const auto* ratio = requireParameter(result, step, "ratio");
    const auto* count = requireParameter(result, step, "count");
    const auto* file = requireParameter(result, step, "file");
    if (output == nullptr || input == nullptr || side == nullptr || mode == nullptr || ratio == nullptr
        || count == nullptr || file == nullptr)
        return false;
    if (!state.prepared())
    {
        const auto whole = [](double value) {
            return value == std::round(value) && value >= 1.0
                && value <= talas::cdp::MixInbetween::maximumCount;
        };
        const auto prepared = *mode == "ratio" ? state.prepare(*ratio)
            : *mode == "count" && whole(*count) && whole(*file)
            ? state.prepareCount(static_cast<int>(*count), static_cast<int>(*file))
            : false;
        if (!prepared)
        {
            addRenderStructuralDiagnostic(result, step.nodeId, {}, "file",
                "CDP Mix Inbetween requires one of its modes and a ratio from 0 to 1, or whole numbers 1 <= file <= count <= 999");
            return false;
        }
    }
    if (!state.process(*input, *side, *output))
    {
        addRenderStructuralDiagnostic(result, step.nodeId, "audioIn", {},
            "CDP Mix Inbetween requires finite input and side chain");
        return false;
    }
    return true;
}

