[[nodiscard]] bool renderCdpDistortShuffle(
    OfflineRenderResult& result,
    const RuntimePlan& plan,
    RenderBuffers& buffers,
    const CompileStep& step,
    talas::cdp::DistortShuffle& state)
{
    auto* output = requireOutputBuffer(
        result, plan, buffers, step, "audioOut", talas::core::PortType::Audio);
    const auto* input = requireInputBuffer(
        result, plan, buffers, step, "audioIn", talas::core::PortType::Audio);
    const auto* domainImage = requireTextParameter(result, step, "domainImage");
    const auto* cycles = requireParameter(result, step, "cycles");
    if (output == nullptr || input == nullptr || domainImage == nullptr || cycles == nullptr)
        return false;
    // CDP reads its shuffle data once, when it starts, and takes Cycles as
    // a breakpoint file, read, rounded, where each domain starts.
    const auto live = cdpFieldFollows(step, "cycles");
    const auto startCycles = live ? std::round(*cycles) : *cycles;
    if (!state.prepared())
    {
        const auto map = talas::cdp::readDistortShuffle(*domainImage);
        if (!map.has_value() || startCycles != std::round(startCycles) || startCycles < 1.0
            || startCycles > talas::cdp::DistortShuffle::maximumCycles
            || !state.prepare(*map, static_cast<int>(startCycles)))
        {
            addRenderStructuralDiagnostic(result, step.nodeId, {}, "domainImage",
                "CDP Distort Shuffle requires a domain of distinct letters, a dash and an image of the same letters each once, and 1 to 32767 cycles");
            return false;
        }
    }
    if (live && !state.setCycles(*cycles))
    {
        addRenderStructuralDiagnostic(result, step.nodeId, {}, "cycles",
            "CDP Distort Shuffle requires a whole number of cycles from 1 to 32767");
        return false;
    }
    if (!state.process(*input, *output))
    {
        addRenderStructuralDiagnostic(result, step.nodeId, "audioIn", {},
            "CDP Distort Shuffle requires finite input");
        return false;
    }
    return true;
}

// CDP's points and overlap, read once, when it starts.
[[nodiscard]] std::optional<std::pair<int, int>> cdpPhaseVocoderSizes(double points, double overlap) noexcept
{
    if (!std::isfinite(points) || points != std::round(points)
        || points < talas::cdp::PhaseVocoder::minimumPoints || points > talas::cdp::PhaseVocoder::maximumPoints
        || !std::isfinite(overlap) || overlap != std::round(overlap) || overlap < 1.0 || overlap > 4.0)
    {
        return std::nullopt;
    }
    return std::pair{static_cast<int>(points), static_cast<int>(overlap)};
}

[[nodiscard]] bool renderCdpPhaseVocoder(
    OfflineRenderResult& result,
    const RuntimePlan& plan,
    const RenderSettings& settings,
    RenderBuffers& buffers,
    const CompileStep& step,
    talas::cdp::PhaseVocoder& state)
{
    auto* output = requireOutputBuffer(
        result, plan, buffers, step, "audioOut", talas::core::PortType::Audio);
    const auto* input = requireInputBuffer(
        result, plan, buffers, step, "audioIn", talas::core::PortType::Audio);
    const auto* points = requireParameter(result, step, "points");
    const auto* overlap = requireParameter(result, step, "overlap");
    if (output == nullptr || input == nullptr || points == nullptr || overlap == nullptr)
        return false;
    // CDP reads its points and overlap once, when it starts.
    if (!state.prepared())
    {
        const auto sizes = cdpPhaseVocoderSizes(*points, *overlap);
        if (!sizes.has_value() || !state.prepare(settings.sampleRate, sizes->first, sizes->second))
        {
            addRenderStructuralDiagnostic(result, step.nodeId, {}, "points",
                "CDP Phase Vocoder requires whole points from 2 to 8192 and an overlap from 1 to 4");
            return false;
        }
    }
    if (!state.process(*input, *output))
    {
        addRenderStructuralDiagnostic(result, step.nodeId, "audioIn", {},
            "CDP Phase Vocoder requires finite input");
        return false;
    }
    return true;
}

