    auto* output = requireOutputBuffer(
        result, plan, buffers, step, "audioOut", talas::core::PortType::Audio);
    constexpr std::array<std::string_view, 7> controlIds{
        "trigger", "frequency", "decayTime", "brightness",
        "pickPosition", "stiffness", "level"};
