                const auto spacingMode = *logSpacing->boolean
                    ? talas::dsp::VocoderBankFrequencySpacing::Logarithmic
                    : talas::dsp::VocoderBankFrequencySpacing::Linear;
                const auto analysisRange = deriveTunableVocoderRange(step,
                    analysisFreq->value, analysisSpacing->value,
                    bandCount, spacingMode);
                const auto synthesisRange = deriveTunableVocoderRange(step,
                    synthesisFreq->value, synthesisSpacing->value,
                    bandCount, spacingMode);
